-- 215 (16/11/2026, lô 51): 9 bài Đọc TCF cho cây Luyện thi TCF, 54 câu, 8 miễn phí, 1 VIP.
-- Sinh bởi scripts/nhap/lo51_doc_tcf.mjs. Mỗi câu một tài liệu riêng (payload.doc). Chạy lại an toàn.
-- TCF-CE-1 #1 Lecture TCF : panneaux et petits messages (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce01', 'practice', 'Lecture TCF : panneaux et petits messages', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• fermeture exceptionnelle : đóng cửa đột xuất (chỉ lần này)\n• en laisse : có dây dắt\n• la pelouse : bãi cỏ\n• emprunter (verbe) : mượn\n• le syndic : ban quản lý chung cư","explications":"• Đọc câu hỏi trước rồi tìm từ khoá trong tài liệu: giờ, ngày, giá, chữ interdit.\n• Tài liệu ngắn thường có nhiều con số: kiểm xem con số nào trả lời đúng câu hỏi.","kyNang":"TCF-CE-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T10:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce01q01', 'lo51tcfce01', 1, 'qcm', 'Quand la boulangerie est-elle fermée ?', '{"doc":"<p><strong>BOULANGERIE DU MARCHÉ</strong></p><p>Fermeture exceptionnelle le mercredi 12 mars.</p><p>Réouverture le jeudi 13 à 7 h.</p>","options":["Le mercredi 12 mars.","Tous les mercredis du mois de mars.","Le jeudi 13 mars.","Le matin à 7 h."]}'::jsonb, '{"answer":0}'::jsonb, 'Biển ghi « Fermeture exceptionnelle le mercredi 12 mars ». « Exceptionnelle » nghĩa là chỉ lần này, không phải mọi thứ Tư.'),
  ('lo51tcfce01q02', 'lo51tcfce01', 2, 'qcm', 'Que demande Karim à Nora ?', '{"doc":"<p>Salut Nora,</p><p>Je suis en retard, mon bus ne passe pas. Commence le film sans moi, j''arrive dans vingt minutes.</p><p>Bises, Karim</p>","options":["De ne pas l''attendre.","De venir le chercher.","D''acheter les billets.","De prendre le bus."]}'::jsonb, '{"answer":0}'::jsonb, 'Karim viết « Commence le film sans moi », tức là đừng chờ anh ấy.'),
  ('lo51tcfce01q03', 'lo51tcfce01', 3, 'qcm', 'Qu''est-ce qui est interdit dans le parc ?', '{"doc":"<p><strong>PARC DES CYGNES</strong></p><p>Chiens acceptés en laisse.</p><p>Vélos interdits sur les pelouses.</p><p>Ouvert de 8 h à 19 h.</p>","options":["Entrer le matin.","Rouler à vélo sur l''herbe.","Venir avec un chien.","Se promener le soir."]}'::jsonb, '{"answer":1}'::jsonb, 'Biển ghi « Vélos interdits sur les pelouses ». Chó vẫn được vào nếu có dây dắt.'),
  ('lo51tcfce01q04', 'lo51tcfce01', 4, 'qcm', 'Que doit faire l''acheteur ?', '{"doc":"<p><strong>Petite annonce</strong></p><p>Vends table en bois et quatre chaises, très bon état. 80 €.</p><p>À venir chercher sur place, 3e étage sans ascenseur.</p><p>Tél. : 06 12 34 56 78</p>","options":["Transporter lui-même les meubles.","Payer la livraison.","Acheter la table et les chaises séparément.","Réparer la table."]}'::jsonb, '{"answer":0}'::jsonb, 'Người bán ghi « À venir chercher sur place »: người mua tự đến lấy.'),
  ('lo51tcfce01q05', 'lo51tcfce01', 5, 'qcm', 'Combien de temps peut-on garder un livre ?', '{"doc":"<p><strong>Médiathèque Jules-Verne</strong></p><p>Vous pouvez emprunter 5 livres et 2 DVD pendant 3 semaines.</p><p>Carte gratuite pour les moins de 18 ans.</p>","options":["Deux semaines.","Cinq semaines.","Trois semaines.","Dix-huit jours."]}'::jsonb, '{"answer":2}'::jsonb, 'Thư viện cho mượn « pendant 3 semaines ». Số 5 và 2 là số sách và số DVD.'),
  ('lo51tcfce01q06', 'lo51tcfce01', 6, 'qcm', 'Quel problème les habitants vont-ils avoir ?', '{"doc":"<p>Chers voisins,</p><p>Des travaux auront lieu dans l''immeuble du 3 au 7 avril. L''eau sera coupée chaque jour de 9 h à 12 h.</p><p>Merci de votre compréhension.</p><p>Le syndic</p>","options":["Pas d''ascenseur ni de lumière dans l''escalier pendant un mois.","Pas d''électricité le soir.","Pas d''eau le matin pendant quelques jours.","Pas de chauffage le week-end."]}'::jsonb, '{"answer":2}'::jsonb, 'Thông báo nói « L''eau sera coupée chaque jour de 9 h à 12 h », từ ngày 3 đến 7 tháng Tư.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-1 #2 Lecture TCF : affiches et courriels courts (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce02', 'practice', 'Lecture TCF : affiches et courriels courts', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• obligatoire (adjectif) : bắt buộc\n• un objet trouvé : đồ nhặt được\n• un trousseau de clés : chùm chìa khoá\n• la pharmacie de garde : hiệu thuốc trực\n• uniquement (adverbe) : chỉ","explications":"• Chữ obligatoire, interdit, uniquement, sauf thường quyết định đáp án.\n• Phương án sai hay lấy một chữ CÓ trong tài liệu nhưng gắn vào sai người, sai thời điểm.","kyNang":"TCF-CE-1","vong":"on","thuTu":2}'::jsonb, '2026-11-16T10:00:01.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce02q01', 'lo51tcfce02', 1, 'qcm', 'Que faut-il porter à la piscine ?', '{"doc":"<p><strong>PISCINE OLYMPE</strong></p><p>Bonnet de bain obligatoire.</p><p>Short de bain interdit : maillot seulement.</p>","options":["Des lunettes de soleil.","Un short de bain.","Un bonnet de bain.","Des chaussures de sport."]}'::jsonb, '{"answer":2}'::jsonb, 'Biển ghi « Bonnet de bain obligatoire ». Quần short bơi thì bị cấm.'),
  ('lo51tcfce02q02', 'lo51tcfce02', 2, 'qcm', 'Pourquoi Pierre écrit-il ?', '{"doc":"<p>Bonjour Madame Leroy,</p><p>Votre fils Lucas a oublié sa veste au club de football hier soir. Elle est à l''accueil.</p><p>Cordialement, Pierre, entraîneur</p>","options":["Pour annuler l''entraînement.","Pour signaler un objet oublié.","Pour vendre une veste.","Pour inscrire Lucas au club de football du quartier."]}'::jsonb, '{"answer":1}'::jsonb, 'Huấn luyện viên báo Lucas « a oublié sa veste au club ».'),
  ('lo51tcfce02q03', 'lo51tcfce02', 3, 'qcm', 'Quand peut-on prendre ce menu ?', '{"doc":"<p><strong>Restaurant Le Petit Pont</strong></p><p>Menu du midi : entrée + plat ou plat + dessert : 14 €</p><p>Du lundi au vendredi uniquement.</p>","options":["Un vendredi soir.","Un dimanche soir.","Un samedi à midi.","Un mardi à midi."]}'::jsonb, '{"answer":3}'::jsonb, 'Thực đơn là « Menu du midi », chỉ áp dụng « Du lundi au vendredi uniquement ».'),
  ('lo51tcfce02q04', 'lo51tcfce02', 4, 'qcm', 'Que doit faire la personne qui a perdu ses clés ?', '{"doc":"<p><strong>OBJET TROUVÉ</strong></p><p>Trouvé dans le bus 12 : un trousseau de clés avec un porte-clés en forme de chat.</p><p>S''adresser à l''agence de la gare.</p>","options":["Prendre le bus 12.","Téléphoner au conducteur.","Attendre à l''arrêt de bus.","Aller à l''agence de la gare."]}'::jsonb, '{"answer":3}'::jsonb, 'Thông báo ghi « S''adresser à l''agence de la gare ».'),
  ('lo51tcfce02q05', 'lo51tcfce02', 5, 'qcm', 'Qu''est-ce qu''Anaïs demande aux amies ?', '{"doc":"<p>Coucou les filles !</p><p>Pour l''anniversaire de Julie samedi, chacune apporte quelque chose à manger. Moi, je fais le gâteau. Pas de cadeau, Julie préfère qu''on parte en week-end ensemble !</p><p>Anaïs</p>","options":["D''acheter un cadeau.","De réserver un hôtel.","D''apporter un plat.","De faire un gâteau."]}'::jsonb, '{"answer":2}'::jsonb, 'Anaïs viết « chacune apporte quelque chose à manger ». Bánh do Anaïs làm, và không mua quà.'),
  ('lo51tcfce02q06', 'lo51tcfce02', 6, 'qcm', 'Que faire si on a besoin d''un médicament à 23 h ?', '{"doc":"<p><strong>Pharmacie de garde</strong></p><p>Ce dimanche, la pharmacie de garde est la Pharmacie Centrale, 4 place de la Mairie.</p><p>Ouverte de 9 h à 20 h. La nuit, appelez le 3237.</p>","options":["Téléphoner au 3237.","Aller à l''hôpital.","Attendre lundi.","Aller place de la Mairie."]}'::jsonb, '{"answer":0}'::jsonb, 'Hiệu thuốc trực mở đến 20 h; ban đêm thì « appelez le 3237 ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-2 #1 Lecture TCF : lettres et courriels (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce03', 'practice', 'Lecture TCF : lettres et courriels', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un fournisseur : nhà cung cấp\n• rembourser (verbe) : hoàn tiền\n• une candidature : đơn ứng tuyển\n• un entretien : buổi phỏng vấn\n• en cas de : trong trường hợp\n• tomber en panne : bị hỏng","explications":"• Đọc dòng « Objet » và câu đầu để biết mục đích bức thư.\n• Câu hỏi mục đích (but, pourquoi … écrit) cần ý của CẢ bức thư, không phải một chi tiết.","kyNang":"TCF-CE-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T10:00:02.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce03q01', 'lo51tcfce03', 1, 'qcm', 'Que propose l''entreprise à la cliente ?', '{"doc":"<p><strong>Objet :</strong> votre commande n° 4527</p><p>Madame,</p><p>Nous sommes désolés : le canapé que vous avez commandé ne sera pas livré le 10 mai comme prévu, car notre fournisseur a pris du retard. Nous pouvons vous le livrer le 24 mai, ou vous rembourser entièrement si vous le souhaitez.</p><p>Le service client</p>","options":["Une livraison le 10 mai.","Une nouvelle date ou un remboursement.","Un canapé moins cher.","Une réduction sur sa prochaine commande."]}'::jsonb, '{"answer":1}'::jsonb, 'Công ty đề nghị giao « le 24 mai, ou vous rembourser entièrement »: hai lựa chọn.'),
  ('lo51tcfce03q02', 'lo51tcfce03', 2, 'qcm', 'Quel est le but de ce courriel ?', '{"doc":"<p>Cher Monsieur Blanc,</p><p>J''ai bien reçu votre candidature pour le poste de vendeur. Votre profil nous intéresse. Pourriez-vous venir à un entretien le mardi 14 à 10 h ? Merci d''apporter une copie de vos diplômes.</p><p>Sophie Garnier, responsable des ressources humaines</p>","options":["Demander une lettre de motivation.","Refuser la candidature.","Inviter le candidat à un entretien.","Proposer directement le poste."]}'::jsonb, '{"answer":2}'::jsonb, 'Bà Garnier hỏi « Pourriez-vous venir à un entretien le mardi 14 à 10 h ? ».'),
  ('lo51tcfce03q03', 'lo51tcfce03', 3, 'qcm', 'Que se passera-t-il s''il pleut ?', '{"doc":"<p><strong>Fête des voisins</strong></p><p>Cette année, la fête aura lieu le 28 juin dans la cour de l''immeuble. Chacun apporte un plat à partager. En cas de pluie, nous nous retrouverons dans la salle commune au rez-de-chaussée.</p><p>L''association des habitants</p>","options":["La fête aura lieu dans une salle de l''immeuble.","Chacun restera chez soi.","La fête sera annulée.","La fête sera reportée au week-end suivant, dans la cour."]}'::jsonb, '{"answer":0}'::jsonb, 'Thông báo ghi « En cas de pluie, nous nous retrouverons dans la salle commune ».'),
  ('lo51tcfce03q04', 'lo51tcfce03', 4, 'qcm', 'Qu''est-ce qui a plu à Hugo ?', '{"doc":"<p>Salut Camille,</p><p>Je t''écris de Montréal ! Le travail se passe bien, mais je trouve l''hiver très long. Heureusement, mes collègues m''ont emmené faire du patin sur un lac gelé : une expérience incroyable ! Je rentre en France en avril.</p><p>Bises, Hugo</p>","options":["Le climat de l''hiver.","Une activité sur la glace.","Son nouveau logement.","Le fait de rentrer bientôt en France."]}'::jsonb, '{"answer":1}'::jsonb, 'Hugo thấy mùa đông dài nhưng việc trượt băng trên hồ là « une expérience incroyable ».'),
  ('lo51tcfce03q05', 'lo51tcfce03', 5, 'qcm', 'Que peuvent faire les familles qui n''ont pas Internet ?', '{"doc":"<p><strong>Mairie de Saint-Aubin : inscriptions à la cantine</strong></p><p>Les inscriptions pour l''année prochaine se font uniquement en ligne, du 1er au 30 juin. Les familles sans accès à Internet peuvent se présenter à l''accueil de la mairie, où un agent les aidera.</p>","options":["S''inscrire en septembre.","Téléphoner à l''école.","Se faire aider à la mairie.","S''inscrire par courrier."]}'::jsonb, '{"answer":2}'::jsonb, 'Gia đình không có Internet « peuvent se présenter à l''accueil de la mairie, où un agent les aidera ».'),
  ('lo51tcfce03q06', 'lo51tcfce03', 6, 'qcm', 'Pourquoi Inès Moreau écrit-elle ?', '{"doc":"<p>Madame, Monsieur,</p><p>J''ai loué un vélo dans votre agence le 3 août. Le vélo est tombé en panne après une heure et j''ai dû rentrer à pied. Je vous demande donc de me rembourser la journée de location.</p><p>Cordialement, Inès Moreau</p>","options":["Pour signaler un accident.","Pour se plaindre et demander de l''argent.","Pour réserver un vélo.","Pour remercier l''agence."]}'::jsonb, '{"answer":1}'::jsonb, 'Chị Inès kể xe hỏng rồi viết « Je vous demande donc de me rembourser »: thư khiếu nại.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-2 #2 Lecture TCF : textes informatifs (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce04', 'practice', 'Lecture TCF : textes informatifs', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la veille : hôm trước\n• le gaspillage : sự lãng phí\n• un demandeur d''emploi : người tìm việc\n• exigé (participe) : bắt buộc phải có\n• une déviation : đường vòng","explications":"• Chú ý chữ sauf, seulement, au moins: chúng đổi nghĩa cả câu.\n• Phân biệt điều kiện « exigé » (bắt buộc) với « un plus » (điểm cộng).","kyNang":"TCF-CE-2","vong":"on","thuTu":2}'::jsonb, '2026-11-16T10:00:03.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce04q01', 'lo51tcfce04', 1, 'qcm', 'Comment fonctionne ce service ?', '{"doc":"<p><strong>Nouveau : le bus à la demande</strong></p><p>Depuis le 1er septembre, les habitants des villages autour de Mérignac peuvent réserver un minibus la veille, par téléphone ou sur l''application. Le minibus les conduit jusqu''à la gare, au même prix qu''un ticket de bus normal.</p>","options":["On réserve le trajet à l''avance.","Le minibus passe toutes les heures.","Le minibus va jusqu''au centre-ville.","Le trajet est gratuit."]}'::jsonb, '{"answer":0}'::jsonb, 'Người dân « peuvent réserver un minibus la veille »: đặt trước một ngày.'),
  ('lo51tcfce04q02', 'lo51tcfce04', 2, 'qcm', 'Que font certains supermarchés ?', '{"doc":"<p><strong>Le saviez-vous ?</strong></p><p>Un Français jette en moyenne 30 kg de nourriture par an. Pour lutter contre ce gaspillage, de plus en plus de supermarchés vendent à prix réduit les produits proches de leur date limite.</p>","options":["Ils jettent moins de 30 kg par an.","Ils ferment plus tôt le soir.","Ils baissent le prix de certains produits.","Ils donnent gratuitement la nourriture invendue aux clients."]}'::jsonb, '{"answer":2}'::jsonb, 'Siêu thị « vendent à prix réduit les produits proches de leur date limite ».'),
  ('lo51tcfce04q03', 'lo51tcfce04', 3, 'qcm', 'Combien paie un étudiant un mardi ?', '{"doc":"<p><strong>Musée des Beaux-Arts</strong></p><p>Le premier dimanche de chaque mois, l''entrée est gratuite pour tous. Les autres jours, le tarif est de 8 €, sauf pour les étudiants et les demandeurs d''emploi, qui paient 4 €.</p>","options":["8 €.","Rien.","2 €.","4 €."]}'::jsonb, '{"answer":3}'::jsonb, 'Giá 8 € « sauf pour les étudiants et les demandeurs d''emploi, qui paient 4 € ». Miễn phí chỉ vào chủ nhật đầu tháng.'),
  ('lo51tcfce04q04', 'lo51tcfce04', 4, 'qcm', 'Quelle condition est obligatoire pour ce poste ?', '{"doc":"<p><strong>Offre d''emploi</strong></p><p>Hôtel du Lac recherche réceptionniste pour la saison d''été (juin à septembre). Anglais exigé, une deuxième langue étrangère est un plus. Travail le week-end. Logement possible sur place.</p>","options":["Parler deux langues étrangères.","Parler anglais.","Être libre en semaine.","Habiter près de l''hôtel."]}'::jsonb, '{"answer":1}'::jsonb, 'Tin tuyển dụng ghi « Anglais exigé ». Ngoại ngữ thứ hai chỉ là điểm cộng (« est un plus »).'),
  ('lo51tcfce04q05', 'lo51tcfce04', 5, 'qcm', 'Selon le texte, que peut-on faire ?', '{"doc":"<p><strong>Conseil santé</strong></p><p>Les médecins recommandent aux adultes de marcher au moins trente minutes par jour. Il n''est pas nécessaire de le faire en une seule fois : trois promenades de dix minutes ont le même effet.</p>","options":["Diviser la marche en plusieurs moments.","Marcher dix minutes par jour.","Marcher seulement le week-end.","Remplacer la marche par trente minutes de vélo chaque jour."]}'::jsonb, '{"answer":0}'::jsonb, 'Văn bản nói « trois promenades de dix minutes ont le même effet »: có thể chia nhỏ.'),
  ('lo51tcfce04q06', 'lo51tcfce04', 6, 'qcm', 'Qui ne pourra pas traverser le pont Wilson ?', '{"doc":"<p><strong>Fermeture du pont Wilson</strong></p><p>Pour des travaux de réparation, le pont Wilson sera fermé aux voitures du 15 au 30 novembre. Les piétons et les cyclistes pourront continuer à l''utiliser. Une déviation sera mise en place par le pont Napoléon.</p>","options":["Les cyclistes.","Les piétons.","Personne.","Les automobilistes."]}'::jsonb, '{"answer":3}'::jsonb, 'Cầu « sera fermé aux voitures »; người đi bộ và xe đạp vẫn qua được.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-3 #1 Lecture TCF : articles d'opinion (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce05', 'practice', 'Lecture TCF : articles d''opinion', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• creuser les inégalités : làm sâu thêm bất bình đẳng\n• nuancé (adjectif) : nhiều sắc thái, không đơn giản\n• le droit à la déconnexion : quyền ngắt kết nối (ngoài giờ)\n• une voie médiane : con đường trung dung\n• mépriser (verbe) : coi thường\n• un compromis : sự thoả hiệp","explications":"• Bài báo hay nêu ý người khác trước, rồi đổi chiều bằng pourtant, mais, en réalité: ý tác giả nằm SAU chữ đó.\n• Phương án chép đúng ý của phía bên kia là bẫy quen thuộc nhất ở mức B2.","kyNang":"TCF-CE-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T10:00:04.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce05q01', 'lo51tcfce05', 1, 'qcm', 'Quelle est la position de l''auteur ?', '{"doc":"<p><strong>Faut-il interdire les devoirs à la maison ?</strong></p><p>Plusieurs pays européens ont réduit, voire supprimé, les devoirs à l''école primaire. Leurs partisans affirment que les devoirs creusent les inégalités : tous les enfants n''ont pas un parent disponible pour les aider. Pourtant, supprimer purement et simplement les devoirs ne me semble pas la solution. Mieux vaudrait organiser, à l''école même, un temps d''étude encadré par des enseignants.</p>","options":["Il préfère des devoirs faits à l''école.","Il veut donner plus de devoirs.","Il pense que les parents doivent aider davantage.","Il veut supprimer tous les devoirs."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả không muốn bỏ hẳn: « Mieux vaudrait organiser, à l''école même, un temps d''étude encadré par des enseignants ».'),
  ('lo51tcfce05q02', 'lo51tcfce05', 2, 'qcm', 'Selon l''auteur, quel est le risque du télétravail ?', '{"doc":"<p><strong>Le télétravail, une liberté surveillée</strong></p><p>On présente souvent le télétravail comme une libération : plus de transports, plus de temps pour soi. La réalité est plus nuancée. Beaucoup de salariés disent avoir du mal à couper : les courriels arrivent le soir, le week-end, et la maison devient un bureau permanent. Sans règles claires sur le droit à la déconnexion, le progrès risque de se transformer en piège.</p>","options":["Passer plus de temps dans les transports.","Perdre son emploi.","Ne plus séparer travail et vie privée.","Travailler moins qu''au bureau."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả nói người làm từ xa « avoir du mal à couper » và nhà thành « un bureau permanent ».'),
  ('lo51tcfce05q03', 'lo51tcfce05', 3, 'qcm', 'Quelle décision la mairie a-t-elle prise ?', '{"doc":"<p><strong>Les trottinettes électriques divisent la ville</strong></p><p>Pour les uns, elles sont une alternative propre à la voiture. Pour les autres, elles encombrent les trottoirs et mettent les piétons en danger. La mairie a choisi une voie médiane : les trottinettes en libre-service restent autorisées, mais elles devront désormais être garées dans des emplacements réservés, sous peine d''amende.</p>","options":["Imposer des places de stationnement.","Réserver les trottoirs aux trottinettes.","Rendre les trottinettes gratuites.","Interdire les trottinettes."]}'::jsonb, '{"answer":0}'::jsonb, 'Thành phố giữ xe nhưng « devront désormais être garées dans des emplacements réservés ».'),
  ('lo51tcfce05q04', 'lo51tcfce05', 4, 'qcm', 'Que conseille l''auteur ?', '{"doc":"<p><strong>Lire, un luxe ?</strong></p><p>On entend dire que les jeunes ne lisent plus. Les chiffres racontent une autre histoire : ils lisent beaucoup, mais pas les livres que l''école attend d''eux. Mangas, romans fantastiques, récits publiés en ligne : ces lectures sont souvent méprisées. C''est une erreur. Plutôt que de juger ce qu''ils lisent, partons de leurs goûts pour les mener vers d''autres textes.</p>","options":["Interdire les mangas à l''école.","Obliger les jeunes à lire les classiques du programme scolaire.","S''appuyer sur les lectures préférées des jeunes.","Publier plus de livres en ligne."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả khuyên « partons de leurs goûts pour les mener vers d''autres textes ».'),
  ('lo51tcfce05q05', 'lo51tcfce05', 5, 'qcm', 'Que pense l''auteur de l''interdiction des locations de courte durée ?', '{"doc":"<p><strong>Tourisme : victime de son succès</strong></p><p>Dans certaines villes, les habitants ne peuvent plus se loger : les appartements sont loués aux touristes, plus rentables. Certains réclament l''interdiction pure et simple des locations de courte durée. La mesure serait sans doute efficace, mais elle priverait de revenus de nombreux propriétaires modestes. Limiter le nombre de nuits par an paraît un compromis plus raisonnable.</p>","options":["Elle serait efficace mais injuste pour certains.","Elle aiderait les petits propriétaires.","Elle est la seule solution possible pour loger les habitants.","Elle serait inutile."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả thừa nhận « La mesure serait sans doute efficace » nhưng « priverait de revenus de nombreux propriétaires modestes ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-3 #2 Lecture TCF : chroniques et débats de société (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce06', 'practice', 'Lecture TCF : chroniques et débats de société', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• relever de l''exploit : gần như là một kỳ tích\n• culpabiliser (verbe) : làm cho thấy có lỗi\n• un péage urbain : phí vào nội đô\n• se méfier de : cảnh giác với\n• un arrêt maladie : nghỉ ốm","explications":"• Câu hỏi « critique », « limite », « risque » thường trỏ tới đoạn sau mais, cependant, or.\n• Đáp án đúng thường DIỄN ĐẠT LẠI văn bản, ít khi chép nguyên chữ.","kyNang":"TCF-CE-3","vong":"on","thuTu":2}'::jsonb, '2026-11-16T10:00:05.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce06q01', 'lo51tcfce06', 1, 'qcm', 'Quelle limite l''auteur souligne-t-il ?', '{"doc":"<p><strong>Le retour du vélo</strong></p><p>Il y a vingt ans, circuler à vélo en ville relevait presque de l''exploit. Aujourd''hui, les pistes cyclables se multiplient et le nombre de cyclistes a doublé. Ce succès ne doit cependant pas faire oublier que les quartiers périphériques restent mal équipés : là où les distances sont les plus longues, le vélo reste une option réservée aux plus courageux.</p>","options":["Les pistes cyclables du centre-ville sont trop dangereuses.","Le nombre de cyclistes diminue.","Le vélo coûte trop cher.","Les quartiers éloignés manquent d''aménagements."]}'::jsonb, '{"answer":3}'::jsonb, 'Tác giả lưu ý « les quartiers périphériques restent mal équipés ».'),
  ('lo51tcfce06q02', 'lo51tcfce06', 2, 'qcm', 'Selon l''auteur, le problème des écrans est lié aussi à…', '{"doc":"<p><strong>Écrans : arrêtons de culpabiliser les parents</strong></p><p>Chaque semaine, une nouvelle étude alerte sur le temps que les enfants passent devant les écrans. Les parents se sentent coupables, mais que peuvent-ils faire quand ils rentrent du travail à 19 h ? Le problème n''est pas seulement familial : il concerne aussi l''offre d''activités sportives et culturelles, souvent trop chères ou trop éloignées.</p>","options":["La mauvaise volonté des parents.","Le prix des écrans.","La qualité des études scientifiques.","Le manque d''activités accessibles."]}'::jsonb, '{"answer":3}'::jsonb, 'Tác giả viết vấn đề còn liên quan đến hoạt động thể thao, văn hoá « souvent trop chères ou trop éloignées ».'),
  ('lo51tcfce06q03', 'lo51tcfce06', 3, 'qcm', 'Quelle critique l''auteur fait-il au péage urbain ?', '{"doc":"<p><strong>Faut-il payer pour entrer dans les villes ?</strong></p><p>Londres et Stockholm l''ont fait : les automobilistes paient pour entrer dans le centre. Résultat, moins d''embouteillages et un air plus pur. L''idée séduit, mais elle pose une question de justice. Le cadre qui habite en centre-ville ne paiera rien, tandis que l''ouvrier qui vit loin et n''a pas de transports en commun paiera tous les jours.</p>","options":["Il rapporte trop peu d''argent à la ville pour être utile.","Il ne réduit pas la pollution.","Il pénalise surtout ceux qui habitent loin.","Il augmente les embouteillages."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả so sánh: người ở trung tâm « ne paiera rien », còn người ở xa « paiera tous les jours ».'),
  ('lo51tcfce06q04', 'lo51tcfce06', 4, 'qcm', 'Que recommande l''auteur aux consommateurs ?', '{"doc":"<p><strong>Les avis en ligne, une confiance fragile</strong></p><p>Avant de choisir un restaurant ou un hôtel, neuf consommateurs sur dix consultent les avis en ligne. Or une partie de ces commentaires sont faux, rédigés par des entreprises spécialisées. Les plateformes promettent de mieux les détecter ; en attendant, mieux vaut se méfier des notes parfaites et lire en priorité les avis détaillés, positifs comme négatifs.</p>","options":["Privilégier les commentaires précis.","Écrire plus d''avis négatifs.","Faire confiance aux meilleures notes.","Ne plus lire les avis en ligne."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả khuyên « se méfier des notes parfaites et lire en priorité les avis détaillés ».'),
  ('lo51tcfce06q05', 'lo51tcfce06', 5, 'qcm', 'Pourquoi l''auteur appelle-t-il à la prudence ?', '{"doc":"<p><strong>Semaine de quatre jours : l''expérience</strong></p><p>Une centaine d''entreprises ont testé la semaine de quatre jours sans baisse de salaire. Les salariés se disent moins fatigués et les arrêts maladie ont diminué. Les résultats sont encourageants, mais prudence : ces entreprises étaient volontaires, souvent petites et dans les services. Rien ne dit que le modèle fonctionnerait dans un hôpital ou une usine.</p>","options":["Les salaires ont baissé.","Les entreprises testées ne représentent pas toutes les situations.","Les arrêts maladie ont augmenté.","Les salariés étaient plus fatigués."]}'::jsonb, '{"answer":1}'::jsonb, 'Các công ty thử nghiệm « étaient volontaires, souvent petites et dans les services », chưa chắc đúng cho bệnh viện hay nhà máy.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-4 #1 Lecture TCF : essais et textes argumentatifs (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce07', 'practice', 'Lecture TCF : essais et textes argumentatifs', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• saisir (verbe) : nắm bắt, hiểu được\n• revendiquer (verbe) : đòi, khẳng định quyền\n• tenir à l''écart : gạt ra ngoài\n• trahir sa mission : phản bội sứ mệnh\n• l''emporter sur : thắng, vượt\n• par confort : vì tiện, vì lười","explications":"• Văn bản C1 hay bác một ý phổ biến trước (« On aurait tort », « Il est devenu banal »): ý tác giả là phần ngược lại.\n• Đọc câu hỏi trước, rồi chỉ đọc kỹ câu chứa câu trả lời để giữ nhịp.","kyNang":"TCF-CE-4","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T10:00:06.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce07q01', 'lo51tcfce07', 1, 'qcm', 'Quelle idée l''auteur défend-il ?', '{"doc":"<p>Nous vivons dans une société qui célèbre la vitesse : livraison en une heure, réponse immédiate aux messages, information en continu. On aurait tort, pourtant, de voir dans la lenteur une simple perte de temps. Certaines choses ne se laissent saisir que dans la durée : une amitié, une compétence, une œuvre. Revendiquer la lenteur, ce n''est donc pas refuser le progrès, mais rappeler qu''il existe des valeurs qui ne se mesurent pas en minutes gagnées.</p>","options":["La lenteur est un refus du progrès.","Certaines choses demandent du temps pour exister.","Gagner du temps est la valeur principale.","La société devrait être plus rapide."]}'::jsonb, '{"answer":1}'::jsonb, 'Tác giả viết « Certaines choses ne se laissent saisir que dans la durée » và nói đề cao sự chậm « ce n''est donc pas refuser le progrès ».'),
  ('lo51tcfce07q02', 'lo51tcfce07', 2, 'qcm', 'Selon l''auteur, les nouvelles activités des musées…', '{"doc":"<p>Le musée a longtemps été pensé comme un temple : on y entrait en silence, pour admirer des chefs-d''œuvre consacrés. Cette conception a eu le mérite de protéger les œuvres, mais elle a aussi tenu à l''écart tous ceux qui ne possédaient pas les codes. Les musées qui s''ouvrent aujourd''hui aux ateliers, aux débats, voire aux concerts, ne trahissent pas leur mission : ils la prolongent, en rappelant qu''une œuvre n''existe vraiment qu''à travers ceux qui la regardent.</p>","options":["Sont fidèles à leur rôle.","Éloignent le public habituel.","Remplacent la mission de conservation.","Mettent les œuvres en danger."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả khẳng định các bảo tàng đó « ne trahissent pas leur mission : ils la prolongent ».'),
  ('lo51tcfce07q03', 'lo51tcfce07', 3, 'qcm', 'Quel est, pour l''auteur, le vrai danger ?', '{"doc":"<p>Il est devenu banal d''opposer intelligence humaine et intelligence artificielle, comme si l''une devait nécessairement l''emporter sur l''autre. Cette rivalité imaginaire masque l''essentiel. La machine calcule, compare, prédit ; elle ne décide pas de ce qui mérite d''être calculé. Le danger n''est pas qu''elle pense à notre place, mais que nous renoncions, par confort, à poser nous-mêmes les questions.</p>","options":["Que la machine devienne plus intelligente que l''homme.","Que la machine fasse des erreurs de calcul.","Que les humains cessent de réfléchir par paresse.","Que les humains rejettent la technologie."]}'::jsonb, '{"answer":2}'::jsonb, 'Mối nguy là « que nous renoncions, par confort, à poser nous-mêmes les questions ».'),
  ('lo51tcfce07q04', 'lo51tcfce07', 4, 'qcm', 'Qu''est-ce qui réveille les souvenirs du personnage ?', '{"doc":"<p><em>Extrait d''un roman</em></p><p>Elle n''était pas revenue au village depuis trente ans. La place lui parut plus petite, la fontaine plus muette. Elle s''attendait à reconnaître chaque façade ; elle ne reconnut que l''odeur du pain, qui sortait toujours de la même boulangerie. Ce fut assez pour que le reste, d''un coup, lui revienne.</p>","options":["Une odeur familière.","La vue de la fontaine.","La rencontre d''un ami.","Les façades de la place."]}'::jsonb, '{"answer":0}'::jsonb, 'Bà không nhận ra mặt tiền nhà nào, chỉ nhận ra « l''odeur du pain », và « Ce fut assez pour que le reste, d''un coup, lui revienne ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-4 #2 Lecture TCF : idées, nuances et implicite (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce08', 'practice', 'Lecture TCF : idées, nuances et implicite', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''entre-soi (nom masculin) : sống khép trong nhóm giống mình\n• la lettre et l''esprit : câu chữ và tinh thần\n• exigeant (adjectif) : khắt khe\n• une lettre de démission : đơn xin nghỉ việc\n• un renoncement : sự từ bỏ\n• désirable (adjectif) : đáng mong muốn","explications":"• Câu « Il serait naïf de… » hai lần liền: tác giả bác cả hai cực rồi mới nêu ý mình.\n• Với đoạn văn chương, câu trả lời thường là điều SUY RA, không viết thẳng: kiểm phương án nào khớp với mọi chi tiết.","isPremium":true,"price":19000,"kyNang":"TCF-CE-4","vong":"on","thuTu":2}'::jsonb, '2026-11-16T10:00:07.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce08q01', 'lo51tcfce08', 1, 'qcm', 'Que pense l''auteur des critiques adressées aux réseaux sociaux ?', '{"doc":"<p>On reproche volontiers aux réseaux sociaux d''enfermer chacun dans ses opinions. Le reproche n''est pas faux, mais il est incomplet : bien avant les algorithmes, nous choisissions déjà nos journaux, nos amis et nos quartiers en fonction de nos préférences. Les réseaux n''ont pas inventé la tentation de l''entre-soi ; ils l''ont rendue plus confortable, et donc plus difficile à percevoir.</p>","options":["Elles sont justes mais oublient une tendance plus ancienne.","Elles exagèrent le rôle des journaux.","Elles sont totalement fausses.","Elles visent les mauvais algorithmes."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả nói lời phê phán « n''est pas faux, mais il est incomplet » và xu hướng đó có từ « bien avant les algorithmes ».'),
  ('lo51tcfce08q02', 'lo51tcfce08', 2, 'qcm', 'Selon l''auteur, un bon traducteur…', '{"doc":"<p>La traduction passe pour un art de la fidélité. Mais à quoi le traducteur doit-il être fidèle : aux mots, ou à l''effet qu''ils produisent ? Traduire mot à mot une plaisanterie, c''est souvent la tuer. Le bon traducteur accepte parfois de s''éloigner de la lettre pour rester fidèle à l''esprit, et cette infidélité apparente est peut-être la forme la plus exigeante de la loyauté.</p>","options":["Doit traduire chaque mot exactement.","Ne doit jamais traduire les plaisanteries, car elles perdent leur sens.","Est infidèle à l''auteur original.","Peut modifier les mots pour garder l''effet du texte."]}'::jsonb, '{"answer":3}'::jsonb, 'Người dịch giỏi « accepte parfois de s''éloigner de la lettre pour rester fidèle à l''esprit ».'),
  ('lo51tcfce08q03', 'lo51tcfce08', 3, 'qcm', 'Que découvre le narrateur en triant les papiers de son père ?', '{"doc":"<p><em>Extrait d''un roman</em></p><p>Mon père parlait peu, et jamais de lui. Quand on lui demandait comment s''était passée sa journée, il répondait « bien », du même ton qu''il aurait dit « il pleut ». Ce n''est que bien plus tard, en triant ses papiers, que j''ai découvert les lettres de démission qu''il avait écrites, chaque année, sans jamais les envoyer.</p>","options":["Son père était malheureux dans son travail.","Son père avait quitté son emploi.","Son père écrivait des romans.","Son père aimait parler de lui."]}'::jsonb, '{"answer":0}'::jsonb, 'Người con tìm thấy thư xin nghỉ việc ông viết « chaque année, sans jamais les envoyer »: ông không vui với công việc nhưng chưa bao giờ nghỉ.'),
  ('lo51tcfce08q04', 'lo51tcfce08', 4, 'qcm', 'Quelle condition de réussite l''auteur évoque-t-il ?', '{"doc":"<p>Il serait naïf de croire que la transition écologique se fera sans renoncements. Il serait tout aussi naïf d''imaginer que l''on convaincra les citoyens en ne leur parlant que de sacrifices. L''histoire montre que les grandes transformations sociales ont réussi lorsqu''elles proposaient, en échange de ce qu''elles retiraient, une vision désirable de l''avenir.</p>","options":["Cacher les sacrifices aux citoyens.","Imposer des renoncements rapides.","Refuser toute transformation sociale.","Offrir un projet d''avenir attirant."]}'::jsonb, '{"answer":3}'::jsonb, 'Theo tác giả, chuyển đổi thành công khi đưa ra « une vision désirable de l''avenir ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-5 #1 Lecture TCF : mini-test en 12 questions (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce09', 'practice', 'Lecture TCF : mini-test en 12 questions', 'TCF', array['Lecture']::text[], 'practice', null, 18, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• mettre fin à : chấm dứt\n• le maraîchage : nghề trồng rau\n• vagabonder (verbe) : lang thang (ý nghĩ)\n• s''espacer (verbe) : thưa dần\n• décréter (verbe) : ra lệnh, áp đặt\n• l''opacité (nom féminin) : sự mù mờ","explications":"• 12 câu trong 18 phút: hai câu đầu mỗi mức nên xong dưới một phút để dành giờ cho C1, C2.\n• TCF không trừ điểm câu sai: hết giờ mà chưa chắc thì vẫn chọn một đáp án.","kyNang":"TCF-CE-5","vong":"chot","thuTu":1}'::jsonb, '2026-11-16T10:00:08.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce09q01', 'lo51tcfce09', 1, 'qcm', 'Quel jour le café est-il fermé ?', '{"doc":"<p><strong>CAFÉ DES AMIS</strong></p><p>Ouvert tous les jours de 7 h à 22 h.</p><p>Fermé le 25 décembre.</p>","options":["Le lundi.","Le 25 décembre.","Le dimanche.","Le 22 décembre."]}'::jsonb, '{"answer":1}'::jsonb, 'Biển ghi « Fermé le 25 décembre ». Ngoài ra quán mở « tous les jours ».'),
  ('lo51tcfce09q02', 'lo51tcfce09', 2, 'qcm', 'Où Emma dort-elle ce soir ?', '{"doc":"<p>Maman,</p><p>Je dors chez Lisa ce soir. Je rentre demain matin avant l''école.</p><p>Bisous, Emma</p>","options":["Chez sa grand-mère.","À l''école.","Chez une amie.","À la maison."]}'::jsonb, '{"answer":2}'::jsonb, 'Emma viết « Je dors chez Lisa ce soir ».'),
  ('lo51tcfce09q03', 'lo51tcfce09', 3, 'qcm', 'Qu''est-ce qui change en mai ?', '{"doc":"<p><strong>Cours de yoga</strong></p><p>Le cours du jeudi soir est déplacé au vendredi, même heure, même salle, pendant tout le mois de mai.</p>","options":["Le professeur.","Le jour du cours.","La salle du cours.","L''heure du cours."]}'::jsonb, '{"answer":1}'::jsonb, 'Lớp chuyển « au vendredi, même heure, même salle »: chỉ đổi ngày.'),
  ('lo51tcfce09q04', 'lo51tcfce09', 4, 'qcm', 'Quand Monsieur Petit peut-il récupérer sa voiture ?', '{"doc":"<p>Bonjour Monsieur Petit,</p><p>Votre voiture est réparée. Vous pouvez venir la chercher à partir de demain 14 h. Attention, le garage ferme à 18 h.</p><p>Garage Martin</p>","options":["Après-demain.","Demain après-midi.","Aujourd''hui avant 18 h.","Demain matin."]}'::jsonb, '{"answer":1}'::jsonb, 'Garage báo « à partir de demain 14 h », và đóng cửa lúc 18 h.'),
  ('lo51tcfce09q05', 'lo51tcfce09', 5, 'qcm', 'Que demande Paul Renard ?', '{"doc":"<p><strong>Objet :</strong> abonnement à la salle de sport</p><p>Madame, Monsieur,</p><p>Je déménage à Nantes le mois prochain et je ne pourrai plus venir à votre salle. Je souhaite donc mettre fin à mon abonnement à partir du 1er mars.</p><p>Paul Renard</p>","options":["D''arrêter son abonnement.","De commencer un abonnement en mars.","De payer moins cher.","De changer de salle à Nantes."]}'::jsonb, '{"answer":0}'::jsonb, 'Anh viết « Je souhaite donc mettre fin à mon abonnement ».'),
  ('lo51tcfce09q06', 'lo51tcfce09', 6, 'qcm', 'Quel est l''un des objectifs du projet ?', '{"doc":"<p><strong>Une ferme en pleine ville</strong></p><p>Sur le toit d''un ancien parking, une association cultive des légumes vendus chaque samedi aux habitants du quartier. Le projet emploie aussi des personnes en recherche d''emploi, formées au maraîchage.</p>","options":["Former des étudiants en agriculture.","Vendre des légumes aux restaurants du centre-ville chaque samedi.","Construire un nouveau parking.","Aider des personnes à trouver du travail."]}'::jsonb, '{"answer":3}'::jsonb, 'Dự án « emploie aussi des personnes en recherche d''emploi ».'),
  ('lo51tcfce09q07', 'lo51tcfce09', 7, 'qcm', 'Selon l''auteur, les bibliothèques…', '{"doc":"<p>Les bibliothèques ont-elles encore un avenir à l''heure d''Internet ? La question revient souvent. Elle oublie que les bibliothèques ne servent plus seulement à prêter des livres : on y vient pour travailler au calme, se faire aider dans des démarches administratives ou simplement rompre la solitude. Leur fréquentation, d''ailleurs, ne baisse pas.</p>","options":["Prêtent de moins en moins de livres.","Ont élargi leur rôle.","Vont bientôt disparaître.","Sont remplacées par Internet."]}'::jsonb, '{"answer":1}'::jsonb, 'Thư viện « ne servent plus seulement à prêter des livres » và lượng người đến « ne baisse pas ».'),
  ('lo51tcfce09q08', 'lo51tcfce09', 8, 'qcm', 'Quelle est la position de l''auteur sur la voiture électrique ?', '{"doc":"<p>On présente souvent la voiture électrique comme la solution miracle à la pollution. C''est aller un peu vite. Si elle ne rejette rien en roulant, sa fabrication, et en particulier celle de la batterie, consomme beaucoup d''énergie et de métaux rares. Elle est un progrès, à condition de rouler moins, pas seulement autrement.</p>","options":["Elle ne pollue pas du tout.","Elle est utile si l''on réduit aussi ses déplacements.","Elle doit être interdite.","Elle pollue davantage que la voiture à essence sur toute sa vie."]}'::jsonb, '{"answer":1}'::jsonb, 'Tác giả nói đó là tiến bộ « à condition de rouler moins, pas seulement autrement ».'),
  ('lo51tcfce09q09', 'lo51tcfce09', 9, 'qcm', 'Que reproche l''auteur à l''usage constant des écrans ?', '{"doc":"<p>On confond volontiers l''ennui avec le vide. Or l''ennui est peut-être la condition même de la création : c''est lorsque rien ne nous occupe que l''esprit se met à vagabonder, à associer des idées éloignées. En remplissant chaque minute libre par un écran, nous ne supprimons pas seulement l''ennui ; nous nous privons de l''espace où naissent les idées neuves.</p>","options":["Il crée trop d''idées inutiles.","Il rend les gens plus ennuyeux.","Il fait perdre la mémoire des choses apprises à l''école.","Il empêche l''esprit de produire des idées."]}'::jsonb, '{"answer":3}'::jsonb, 'Dùng màn hình mọi lúc rảnh làm ta « nous nous privons de l''espace où naissent les idées neuves ».'),
  ('lo51tcfce09q10', 'lo51tcfce09', 10, 'qcm', 'Que comprend-on de la relation entre les deux personnages ?', '{"doc":"<p><em>Extrait d''un roman</em></p><p>Il avait promis d''écrire chaque semaine. Les premières lettres furent longues, pleines de détails sur la ville et le travail. Puis elles raccourcirent, s''espacèrent. La dernière tenait en trois lignes et parlait du temps qu''il faisait. Elle la relut plusieurs fois, comme on cherche, dans un silence, ce qu''il ne dit pas.</p>","options":["Elle devient plus forte.","Elle s''éloigne peu à peu.","Elle commence à peine.","Elle reste toujours la même."]}'::jsonb, '{"answer":1}'::jsonb, 'Thư ngắn dần, thưa dần (« elles raccourcirent, s''espacèrent ») và lá cuối chỉ nói chuyện thời tiết: hai người xa nhau dần.'),
  ('lo51tcfce09q11', 'lo51tcfce09', 11, 'qcm', 'Que rejette l''auteur ?', '{"doc":"<p>Toute mémoire collective est sélective : une nation se souvient de ce qui la grandit et oublie volontiers ce qui la dérange. Prétendre corriger cet oubli en multipliant les commémorations serait illusoire ; on ne décrète pas le souvenir. C''est par l''enseignement patient de l''histoire, dans ce qu''elle a de complexe et d''inconfortable, qu''une société apprend à se regarder en face.</p>","options":["Le souvenir des événements dérangeants.","L''idée que la mémoire collective est sélective.","L''enseignement de l''histoire.","L''idée que les cérémonies suffisent à entretenir la mémoire."]}'::jsonb, '{"answer":3}'::jsonb, 'Tác giả nói nhân nhiều lễ tưởng niệm « serait illusoire ; on ne décrète pas le souvenir ».'),
  ('lo51tcfce09q12', 'lo51tcfce09', 12, 'qcm', 'Quel paradoxe l''auteur décrit-il ?', '{"doc":"<p>Le paradoxe de la transparence est qu''elle peut produire l''opacité. À force d''exiger que tout soit publié, rapports, chiffres, comptes rendus, on noie l''information essentielle sous une masse de documents que personne ne lit. La véritable transparence ne consiste pas à tout montrer, mais à rendre compréhensible ce qui compte.</p>","options":["Trop d''informations publiées rend la vérité moins visible.","Personne ne veut publier de chiffres.","La transparence oblige les institutions à cacher certaines informations.","Les documents publiés sont souvent faux."]}'::jsonb, '{"answer":0}'::jsonb, 'Đòi công bố mọi thứ khiến « on noie l''information essentielle sous une masse de documents que personne ne lit ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
